const INK = '#1f2a37';
const COL_A = '#c0392b';
const COL_B = '#2166ac';
const COL_C = '#c46a12';
const COL_D = '#1f7a45';

const TEXT_SPECS = [
  { id: 'eq0', s: '1' },
  { id: 'eq1', s: 'x²' },
  { id: 'eq2', s: ' − 3' },
  { id: 'eq3', s: 'x' },
  { id: 'eq4', s: ' + 2' },
  { id: 'eq5', s: ' = 0' },
  { id: 'chipA', s: 'a = 1' },
  { id: 'chipB', s: 'b = −3' },
  { id: 'chipC', s: 'c = 2' },
  { id: 'num', s: '−b ± √(b² − 4ac)' },
  { id: 'den', s: '2a' },
  { id: 'xeq', s: 'x =' },
  { id: 'deltaPre', s: 'Δ = b² − 4ac = (−3)² − 4·1·2 = 9 − 8' },
  { id: 'deltaRes', s: ' = 1' }
];

function charFactor(ch) {
  if (ch === ' ') return 0.32;
  if (ch === '²') return 0.46;
  if (ch === '·') return 0.36;
  if (ch === '(' || ch === ')' || ch === '[' || ch === ']') return 0.36;
  if (ch === 'Δ' || ch === '√' || ch === '±') return 0.70;
  if (ch === '−' || ch === '+' || ch === '=' || ch === '/') return 0.62;
  return 0.60;
}

function estWidth(s, fontSize) {
  var w = 0;
  for (var i = 0; i < s.length; i++) w += charFactor(s.charAt(i));
  return w * fontSize;
}

const visual = {
  prepare: function (input) {
    var out = [];
    for (var i = 0; i < TEXT_SPECS.length; i++) {
      out.push({ kind: 'text', payload: TEXT_SPECS[i].s });
    }
    return out;
  },
  render: function (input, metrics) {
    var W = 720, H = 480;
    if (input && input.viewport) {
      if (typeof input.viewport.widthDu === 'number' && input.viewport.widthDu > 0) W = input.viewport.widthDu;
      if (typeof input.viewport.heightDu === 'number' && input.viewport.heightDu > 0) H = input.viewport.heightDu;
    }

    var indexOf = {};
    for (var i = 0; i < TEXT_SPECS.length; i++) indexOf[TEXT_SPECS[i].id] = i;

    function spec(id) { return TEXT_SPECS[indexOf[id]]; }

    function metricWidth(id, fontSize) {
      var j = indexOf[id];
      var item = null;
      if (Array.isArray(metrics)) item = metrics[j];
      else if (metrics && typeof metrics === 'object') {
        if (Array.isArray(metrics.measurements)) item = metrics.measurements[j];
        else if (Array.isArray(metrics.items)) item = metrics.items[j];
        else if (Array.isArray(metrics.texts)) item = metrics.texts[j];
        else if (metrics[j]) item = metrics[j];
      }
      if (item && typeof item === 'object') {
        var w = typeof item.width === 'number' ? item.width : (item.box && typeof item.box.width === 'number' ? item.box.width : null);
        if (typeof w === 'number' && isFinite(w) && w > 0) return w;
      }
      return estWidth(spec(id).s, fontSize);
    }

    var paths = [];
    var nodes = [];
    var pid = 0;

    function addPath(cmds, stroke, sw) {
      var id = 'p' + pid;
      pid = pid + 1;
      paths.push({ id: id, commands: cmds });
      nodes.push({ type: 'path', pathId: id, stroke: stroke, strokeWidth: sw, fill: 'none' });
    }

    function addLabel(text, x, y, size, color, weight) {
      nodes.push({ type: 'label', text: text, x: x, y: y, fontSize: size, fill: color, fontWeight: weight || '500' });
    }

    var fe = Math.min(60, Math.max(26, W * 0.075));
    var eqIds = ['eq0', 'eq1', 'eq2', 'eq3', 'eq4', 'eq5'];
    var eqCols = [COL_A, INK, COL_B, INK, COL_C, INK];
    var eqW = [];
    var eqX = [];
    var totalEq = 0;
    var k;

    for (k = 0; k < 6; k++) {
      eqW[k] = metricWidth(eqIds[k], fe);
      totalEq += eqW[k];
    }
    if (totalEq > W - 48) {
      fe = Math.max(18, fe * (W - 48) / totalEq);
      totalEq = 0;
      for (k = 0; k < 6; k++) {
        eqW[k] = estWidth(spec(eqIds[k]).s, fe);
        totalEq += eqW[k];
      }
    }

    var eqY = H * 0.14;
    var cursor = (W - totalEq) / 2;
    for (k = 0; k < 6; k++) {
      eqX[k] = cursor;
      cursor += eqW[k];
    }

    for (k = 0; k < 6; k++) {
      var isCoef = (k === 0 || k === 2 || k === 4);
      addLabel(spec(eqIds[k]).s, eqX[k], eqY, fe, eqCols[k], isCoef ? '700' : '500');
    }

    var barY = eqY + 10;
    for (k = 0; k < 6; k++) {
      if (k === 0 || k === 2 || k === 4) {
        addPath(visualSdk.polyline([[eqX[k] + 2, barY], [eqX[k] + eqW[k] - 2, barY]]), eqCols[k], 6);
      }
    }

    var fc = Math.min(30, Math.max(16, W * 0.036));
    var chipIds = ['chipA', 'chipB', 'chipC'];
    var chipCols = [COL_A, COL_B, COL_C];
    var chipTw = [];
    var chipW = 120;
    for (k = 0; k < 3; k++) {
      chipTw[k] = metricWidth(chipIds[k], fc);
      if (chipTw[k] + 40 > chipW) chipW = chipTw[k] + 40;
    }
    var chipH = Math.max(44, H * 0.11);
    var chipGap = 34;
    var rowW = chipW * 3 + chipGap * 2;
    var rowX = (W - rowW) / 2;
    var chipY = H * 0.44;
    var chipCx = [];

    for (k = 0; k < 3; k++) {
      var cx0 = rowX + k * (chipW + chipGap);
      chipCx[k] = cx0 + chipW / 2;
      addPath(visualSdk.polyline([[cx0, chipY], [cx0 + chipW, chipY], [cx0 + chipW, chipY + chipH], [cx0, chipY + chipH], [cx0, chipY]]), chipCols[k], 2);
      addLabel(spec(chipIds[k]).s, cx0 + (chipW - chipTw[k]) / 2, chipY + chipH * 0.68, fc, chipCols[k], '700');
    }

    for (k = 0; k < 3; k++) {
      var srcK = k * 2;
      var sx = eqX[srcK] + eqW[srcK] / 2;
      addPath(visualSdk.polyline([[sx, barY + 4], [chipCx[k], chipY]]), chipCols[k], 1.6);
    }

    var ff = Math.min(30, Math.max(16, W * 0.036));
    var numW = metricWidth('num', ff);
    var denW = metricWidth('den', ff);
    var xeqW = metricWidth('xeq', ff);
    var fracW = Math.max(numW, denW) + 20;
    var totalF = xeqW + 14 + fracW;
    var fx = (W - totalF) / 2;
    var fBarY = H * 0.70;
    var fracX = fx + xeqW + 14;

    addLabel(spec('xeq').s, fx, fBarY + ff * 0.34, ff, INK, '600');
    addPath(visualSdk.polyline([[fracX, fBarY], [fracX + fracW, fBarY]]), INK, 2);
    addLabel(spec('num').s, fracX + (fracW - numW) / 2, fBarY - 12, ff, INK, '600');
    addLabel(spec('den').s, fracX + (fracW - denW) / 2, fBarY + ff * 1.35, ff, INK, '600');

    var fd = Math.min(26, Math.max(15, W * 0.032));
    var preW = metricWidth('deltaPre', fd);
    var resW = metricWidth('deltaRes', fd);
    var dx = (W - (preW + resW)) / 2;
    var dy = H * 0.885;

    addLabel(spec('deltaPre').s, dx, dy, fd, INK, '500');
    addLabel(spec('deltaRes').s, dx + preW, dy, fd, COL_D, '700');

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula-diagram',
      revision: input && typeof input.revision !== 'undefined' ? input.revision : 0,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
